def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    import heapq

    events = []
    for i, op in enumerate(ops):
        l, r = op[1], op[2]
        events.append((l, 1, i))
        events.append((r + 1, -1, i))
    events.sort()

    active = [False] * len(ops)
    erases = []
    paints = []
    counts = {}
    prev = events[0][0]
    j = 0

    while j < len(events):
        x = events[j][0]

        while erases and not active[-erases[0] - 1]:
            heapq.heappop(erases)

        erase_time = -erases[0] - 1 if erases else -1

        while paints:
            neg_color, neg_time = paints[0]
            time = -neg_time
            if not active[time] or time <= erase_time:
                heapq.heappop(paints)
            else:
                break

        if paints and x > prev:
            color = -paints[0][0]
            counts[color] = counts.get(color, 0) + x - prev

        while j < len(events) and events[j][0] == x:
            _, kind, i = events[j]
            if kind == 1:
                active[i] = True
                if ops[i][0] == 0:
                    heapq.heappush(erases, -i - 1)
                else:
                    heapq.heappush(paints, (-ops[i][3], -i))
            else:
                active[i] = False
            j += 1

        prev = x

    return [[color, counts[color]] for color in sorted(counts)]
